head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/

scwin.vScrenID = "ULDFIS00219.xml";
// 전역 변수 선언
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsStrtDt = ""; // 조회조건 결산시작일자
scwin.vAcntclsEndDt = ""; // 조회조건 결산종료일자

/**
 *  화면이 최초 로드될때 실행되는 초기화 이벤트
 *  (초기 데이터 조회나 컴포넌트 설정) 
 */

// scwin.onpageload, scwin.onpageunload 함수
scwin.onpageload = function() {
    scwin.init();
};

/**
 *  현재 로딩된 페이지가 초기화되거나 종료될때(다른 화면으로 이동하거나 페이지를 닫기전) 발생하는 이벤트
 *  (주로 SPA(Single Page Application) 환경에서 전역 자원을 해제하거나 메모리 누수 방지)
 */
scwin.onpageunload = function() {
};

// 일반 함수
/**
 *  화면 초기화
 */
scwin.init = function() {

    // 결산일자 조회
    // 결산일자 From To 변경
    //frame.Provider("../frame_head").fn_SrchAcntclsDt();

    scwin.search();

};

/**
 *  데이터셋 초기화
 */
scwin.initDs = function() {
    dlt_executiveStatusListRes.setData([]);
};

/**
 *  조회조건 유효성 체크
 */
scwin.chkValid = function() {

    // 필수항목 체크
    scwin.vKisCd = $p.parent().frame_head.getWindow().scwin.fn_GetKisCd();
    scwin.vAcntclsStrtDt = $p.parent().frame_head.getWindow().scwin.fn_GetAcntclsStrtDt();
    scwin.vAcntclsEndDt = $p.parent().frame_head.getWindow().scwin.fn_GetAcntclsEndDt();

    if (scwin.vKisCd === "" || scwin.vAcntclsStrtDt === "" || scwin.vAcntclsEndDt === "") {
        return false;
    }

    return true;

};

/**
 * 경영진구성 조회
 */
scwin.search = async function () {

    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크
    if (!scwin.chkValid()) {
        return;
    }

    dma_executiveStatusInfoReq.set("kisCd", scwin.vKisCd);
    dma_executiveStatusInfoReq.set("stdStrtDt", scwin.vAcntclsStrtDt);
    dma_executiveStatusInfoReq.set("stdEndDt", scwin.vAcntclsEndDt);

    const sbmOptions = {
        id : "sbm_executiveStatus",
        action : "/api/listing/nice/company-status/executive-status",
        method : "get",
        ref : "dma_executiveStatusInfoReq",
        target : "dlt_executiveStatusListRes|append",
        gridview : "grd_mngAdmCompst",
        isProcessMsg : false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    dlt_executiveStatusListRes.setJSON(res.responseJSON.body);

};

/**
 *  엑셀파일다운로드
 */
scwin.excelDownload = function() {

    if (dlt_executiveStatusListRes.getRowCount() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }

    const options = {
        fileName : "경영진구성",
        sheetName : "경영진구성"
    };

    const infoArray = {};

    $c.data.downloadGridViewExcel(grd_mngAdmCompst, options, infoArray);

};
